package net.officefloor.hq.app.sheet;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/** A sheet, chosen by its id; everything else in the app is kept per sheet. */
@Entity
@Table(name = "sheet")
public class Sheet {

    @Id
    private String id;

    /** The sheet's today: every date decision and default date uses it, never the real clock. */
    @Column(nullable = false)
    private LocalDate today;

    /** The clerk limit: a clerk settles a claim only when its due is at or below it; null when there is none. */
    @Column(name = "clerk_limit", precision = 19, scale = 2)
    private BigDecimal clerkLimit;

    /** The floor: a claim's live due is at least it; a sheet starts at 1.00. */
    @Column(nullable = false, precision = 19, scale = 2)
    private BigDecimal floor = Sheet.DEFAULT_FLOOR;

    /** The terms: a claim is due by its date plus this many days; a sheet starts at 14. */
    @Column(nullable = false)
    private int terms = Sheet.DEFAULT_TERMS;

    /** The late percent: an overdue claim's due gains it of its figure for every full 30 days overdue; a sheet starts at 0.00. */
    @Column(name = "late_pct", nullable = false, precision = 19, scale = 2)
    private BigDecimal latePct = Sheet.DEFAULT_LATE_PCT;

    /** The policy date: a claim dated before it rounds half up, one on or after it half to even; null (blank) for
     *  the sheet's today. */
    @Column(name = "policy_date")
    private LocalDate policyDate;

    /** The period numbering from: while the sheet's today is on or after it, a claim opened is numbered within its
     *  period; null (blank) for off. */
    @Column(name = "period_numbering_from")
    private LocalDate periodNumberingFrom;

    /** The late percent a sheet starts at. */
    public static final BigDecimal DEFAULT_LATE_PCT = new BigDecimal("0.00");

    /** The terms a sheet starts at. */
    public static final int DEFAULT_TERMS = 14;

    /** The floor a sheet starts at. */
    public static final BigDecimal DEFAULT_FLOOR = new BigDecimal("1.00");

    protected Sheet() {
    }

    public Sheet(String id) {
  return useQuery({
    queryKey: claimsQueryKey(sheet ?? ''),
    queryFn: () => getJson<Claim[]>(claimsPath(sheet ?? '')),
    enabled: !!sheet,
  });
}

/** An amount ("12.50") in whole cents, so sums are exact. */
const cents = (amount: string) => Math.round(Number(amount) * 100);

/** A sum of the counted (OPEN, PENDING and SETTLED) claims' amounts, with two decimals; a held person's OPEN claims
 *  are left out. */
export function sumOf(claims: Claim[], held: Set<number> = new Set()): string {
  return (claims.filter((c) => countsLive(c, held)).reduce((n, c) => n + cents(c.amount), 0) / 100).toFixed(2);
}

/** A claim's due-by (YYYY-MM-DD): its date plus the terms in force, in days. */
export function dueByOf(c: Claim, terms: string): string {
  const d = new Date(`${c.date}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + Number(terms));
  return d.toISOString().slice(0, 10);
}

/** Whether a claim is overdue: it is OPEN or PENDING and its due-by is before the sheet's today. */
export const isOverdue = (c: Claim, terms: string, today: string | undefined) =>
  isOpen(c) && today !== undefined && dueByOf(c, terms) < today;

/** The id of the claim whose editor is open (search param `editClaim`), or '' for none. */
export const useEditingClaim = () => useSearchParam('editClaim', asString);

/** The ids of the selected claims (search param `selectedClaims`, comma-separated), a toggle for one, and a
 *  clear. The toggle works from the URL as it is when it runs, so quick clicks in a row each keep the others'. */
export function useSelectedClaims() {
  const [ids] = useSearchParam('selectedClaims', asIds);
  const navigate = useNavigate();
  const update = (change: (ids: Set<number>) => void) =>
    void navigate({
      to: '.',
      search: (prev: Record<string, unknown>) => {
        const next = { ...prev };
        const set = new Set(asIds(prev.selectedClaims));
        change(set);
        if (set.size === 0) delete next.selectedClaims;
        else next.selectedClaims = [...set].join(',');
        return next;
      },
      replace: true,
    });
  return {
    selected: new Set(ids),
    toggle: (id: number, on: boolean) => update((set) => (on ? set.add(id) : set.delete(id))),
    clear: () => update((set) => set.clear()),
  };
}

const asIds = (raw: unknown): number[] =>
  raw === undefined || raw === null || raw === ''
    ? []
    : String(raw).split(',').map(Number).filter((n) => Number.isInteger(n));
import { useQuery } from '@tanstack/react-query';
